
clear all, close all,

load('Q2data.mat','x','labels','gmmParameters');

lossMatrix = [0 1 1;
    1 0 1;
    1 1 0];

[decisions,confusionMatrix] = ...
    performERMclassificationGMMdata(x,labels,gmmParameters,lossMatrix,0);

% AI-assisted: Adapt 2D plotting code example from class to 3D

mShapes = 'o^s';
mColors = 'gr';

figure(1), clf, %[output:4cfb7230]

for l = 1:3
    for d = 1:3

        ind_dl = find(decisions==d & labels==l);

        if d==l
            color = mColors(1);
        else
            color = mColors(2);
        end

        plot3(x(1,ind_dl),x(2,ind_dl),x(3,ind_dl), ... %[output:4cfb7230]
            strcat(mShapes(l),color),'MarkerSize',4); %[output:4cfb7230]

        hold on,

    end
end

xlabel('x_1'), %[output:4cfb7230]
ylabel('x_2'), %[output:4cfb7230]
zlabel('x_3'), %[output:4cfb7230]
title('3D MAP Classification Results'), %[output:4cfb7230]
grid on, %[output:4cfb7230]
view(3), %[output:4cfb7230]

exportgraphics(figure(1),'Q2_A3_3D.png','Resolution',300); %[output:4cfb7230]


